export const customInstance = async <T>(requestConfig: {
  url: string;
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  params?: Record<string, string | number | boolean | undefined>;
  data?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  responseType?: 'json' | 'blob' | 'text';
}): Promise<T> => {
  const config = getApiClientConfig();
  const { url, method, params, data, headers, signal, responseType = 'json' } = requestConfig;
  const token = await config.getAccessToken();

  const queryString = params
    ? '?' + new URLSearchParams(
        Object.entries(params)
          .filter(([, v]) => v !== undefined)
          .map(([k, v]) => [k, String(v)])
      ).toString()
    : '';

  const response = await fetch(`${config.baseUrl}${url}${queryString}`, {
    method,
    headers: {
      ...(data && responseType === 'json' ? { 'Content-Type': 'application/json' } : {}),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...headers,
    },
    body: data ? JSON.stringify(data) : undefined,
    signal,
  });

  if (!response.ok) {
    const err = new Error(`HTTP error! status: ${response.status}`);
    (err as Error & { status: number }).status = response.status;
    throw err;
  }

  if (responseType === 'blob') return response.blob() as Promise<T>;
  if (responseType === 'text') return response.text() as Promise<T>;
  const text = await response.text();
  if (!text.trim()) return undefined as T;
  return JSON.parse(text);
};

export default customInstance;

// Re-export axios types that consumers need for IPFS upload (progress, cancel)
export type { AxiosInstance, AxiosProgressEvent, CancelToken };
export { default as axios } from 'axios';

